<template><main class="min-h-screen bg-slate-50 flex items-center justify-center p-5"><section class="w-full max-w-md bg-white border rounded-2xl p-7"><NuxtLink to="/" class="text-xl font-bold text-emerald-800">AgriStellar</NuxtLink><h1 class="text-2xl font-semibold mt-6 mb-3">{{ linking?'Liên kết Privy':'Đăng nhập bằng Privy' }}</h1><p class="text-sm text-slate-500 leading-6 mb-5">Email OTP xác thực tài khoản. Ví Stellar và quyền ký giao dịch được kết nối riêng qua Wallets Kit.</p><p v-if="!configuration?.configured" class="p-4 bg-amber-50 text-sm rounded-lg mb-5">Privy chưa được cấu hình. Sử dụng tài khoản và mật khẩu hiện có.</p><p v-if="notice" role="status" class="p-3 bg-amber-50 text-sm rounded-lg mb-5">{{ notice }}</p><form v-if="configuration?.configured" class="space-y-4" @submit.prevent="step==='email'?sendCode():verifyCode()"><label class="block text-sm">Email<input v-model="email" type="email" required class="mt-2 w-full rounded-lg border-slate-300" :disabled="step!=='email'"/></label><template v-if="step==='code'"><label class="block text-sm">Mã OTP<input v-model="code" inputmode="numeric" autocomplete="one-time-code" required class="mt-2 w-full rounded-lg border-slate-300"/></label><label v-if="!linking" class="block text-sm">Vai trò<select v-model="role" class="mt-2 w-full rounded-lg border-slate-300"><option>Buyer</option><option>Supplier</option></select></label></template><button :disabled="busy" class="w-full bg-emerald-700 text-white rounded-lg px-4 py-2.5 disabled:opacity-50">{{ busy?'Đang xử lý…':step==='email'?'Nhận mã OTP':linking?'Xác minh và liên kết':'Xác minh và đăng nhập' }}</button></form><NuxtLink to="/login" class="inline-block text-sm text-emerald-700 underline mt-5">Đăng nhập bằng mật khẩu</NuxtLink></section></main></template>
<script setup lang="ts">
definePageMeta({layout:'default'});const route=useRoute();const linking=computed(()=>route.query.mode==='link');const {request}=usePlatform();const store=useAuthStore();const configuration=ref<any>(null);const email=ref('');const code=ref('');const role=ref('Buyer');const step=ref('email');const busy=ref(false);const notice=ref('');let privy:any;
async function client(){if(!privy){const {default:Privy,InMemoryCache}=await import('@privy-io/js-sdk-core');privy=new Privy({appId:configuration.value.appId,storage:new InMemoryCache()});await privy.initialize();}return privy;}
async function sendCode(){busy.value=true;notice.value='';try{if(linking.value&&!useCookie('access_token').value)throw new Error('Đăng nhập tài khoản AgriStellar trước khi liên kết.');const p=await client();await p.auth.email.sendCode(email.value);step.value='code';}catch(e:any){notice.value=e.message||'Không gửi được OTP';}finally{busy.value=false;}}
async function verifyCode(){busy.value=true;notice.value='';try{const p=await client();await p.auth.email.loginWithCode(email.value,code.value);const accessToken=await p.getAccessToken();if(!accessToken)throw new Error('Privy chưa trả access token');if(linking.value){await request('/auth/privy/link','POST',{accessToken});await navigateTo('/workspace/settings');return;}const identityToken=await p.getIdentityToken();const result=await request('/auth/privy/login','POST',{accessToken,...(identityToken?{identityToken}:{}),role:role.value});useCookie('access_token',{maxAge:900,sameSite:'lax'}).value=result.accessToken;useCookie('refresh_token',{maxAge:604800,sameSite:'lax'}).value=result.refreshToken;store.setUser(result.user);await navigateTo('/workspace');}catch(e:any){notice.value=e.data?.error?.message||e.message||'Không xác minh được';}finally{busy.value=false;}}
onMounted(async()=>{try{configuration.value=await request('/auth/privy/config');}catch(e:any){notice.value=e.data?.error?.message||e.message;}});
</script>
